mapper.select:
/* AppAttd01Mapper.selectSiteName */
SELECT
      S.SITE_NM
  FROM TB_SITE S
 WHERE S.CMPNY_CD = #{cmpnyCd}
   AND S.SITE_CD  = #{siteCd}
 LIMIT 1

/* AppAttd01Mapper.countFullDayLeaveOn */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.SITE_CD       = #{siteCd}
   AND U.USER_CD       = #{userCd}
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
   AND U.USE_UNIT_TYPE = '00'
   AND U.START_DATE   <= #{workYmd}
   AND U.END_DATE     >= #{workYmd}

/* AppAttd01Mapper.selectGpsByAttdIds */ SELECT G.ATTD_ID AS attdId , G.GPS_INFO_TYPE AS gpsInfoType , G.IS_MOCKED AS isMocked , G.ACCURACY AS accuracy , G.API_CALL_DATE AS apiCallDate , G.API_CALL_TIME AS apiCallTime , S.GPS_RANGE AS siteGpsRange FROM TB_USER_ATTD_GPS G LEFT JOIN TB_SITE S ON S.CMPNY_CD = G.CMPNY_CD AND S.SITE_CD = G.SITE_CD WHERE G.CMPNY_CD = #{cmpnyCd} AND G.ATTD_ID IN
#{id}
ORDER BY G.ATTD_ID, G.GPS_INFO_TYPE, G.API_CALL_DATE DESC, G.API_CALL_TIME DESC

/* AppAttd01Mapper.selectOvertimeYmds */
SELECT DISTINCT T.WORK_YMD
  FROM (
        SELECT OM.WORK_YMD
          FROM TB_USER_OVERTIME_MGMT OM
         WHERE OM.CMPNY_CD = #{q.cmpnyCd}
           AND OM.SITE_CD  = #{q.siteCd}
           AND OM.USER_CD  = #{q.userCd}
           AND OM.DEL_YN   = 'N'
           AND OM.OT_STATUS <> 'CANCELLED'
           AND OM.WORK_YMD BETWEEN #{q.fromYmd} AND #{q.toYmd}
        UNION
        SELECT RQ.WORK_YMD
          FROM TB_USER_ATTD_REQ RQ
         WHERE RQ.CMPNY_CD = #{q.cmpnyCd}
           AND RQ.SITE_CD  = #{q.siteCd}
           AND RQ.USER_CD  = #{q.userCd}
           AND RQ.DEL_YN   = 'N'
           AND RQ.REQ_TYPE IN ('03', '04')
           AND RQ.REQ_STATUS IN ('01', '02')
           AND RQ.WORK_YMD BETWEEN #{q.fromYmd} AND #{q.toYmd}
       ) T

/* AppAttd01Mapper.selectUserNodeCd */
SELECT
      U.NODE_CD
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USER_CD  = #{userCd}
 LIMIT 1

/* AppAttd01Mapper.countCoveringClose */


    SELECT COUNT(*)
      FROM TB_ATTD_CLOSE C
     WHERE C.CMPNY_CD     = #{cmpnyCd}
       AND C.SITE_CD      = #{siteCd}
       AND C.CLOSE_YM     = #{closeYm}
       AND C.CLOSE_STATUS = 'CLOSED'
       AND C.NODE_CD      = '*'


    WITH RECURSIVE anc AS (
        SELECT N.NODE_CD, N.PARENT_NODE_CD
          FROM TB_SITE_NODE N
         WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
        UNION ALL
        SELECT P.NODE_CD, P.PARENT_NODE_CD
          FROM TB_SITE_NODE P
          JOIN anc A2
            ON P.CMPNY_CD = #{cmpnyCd} AND P.SITE_CD = #{siteCd} AND P.NODE_CD = A2.PARENT_NODE_CD
    )
    SELECT COUNT(*)
      FROM TB_ATTD_CLOSE C
     WHERE C.CMPNY_CD     = #{cmpnyCd}
       AND C.SITE_CD      = #{siteCd}
       AND C.CLOSE_YM     = #{closeYm}
       AND C.CLOSE_STATUS = 'CLOSED'
       AND (
            C.NODE_CD = '*'
         OR C.NODE_CD = #{nodeCd}
         OR (C.INC_SUB_YN = 'Y' AND C.NODE_CD IN (SELECT NODE_CD FROM anc WHERE NODE_CD != #{nodeCd}))
       )

/* AppAttd01Mapper.selectOpenAttd */
SELECT
      A.ATTD_ID        AS attdId
    , A.WORK_YMD       AS workYmd
    , A.WORK_SEQ       AS workSeq
    , A.SITE_CD        AS siteCd
    , A.NODE_CD        AS nodeCd
    , A.CHECK_OUT_TIME AS checkOutTime
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.DEL_YN   = 'N'
   AND A.CHECK_IN_TIME IS NOT NULL
   AND A.CHECK_OUT_TIME IS NULL
   AND A.WORK_YMD >= #{fromYmd}

   AND A.WORK_YMD = #{workYmd}

 ORDER BY A.WORK_YMD DESC, A.WORK_SEQ DESC
 LIMIT 1

/* AppAttd01Mapper.selectReCheckOutTarget */
SELECT
      A.ATTD_ID        AS attdId
    , A.WORK_YMD       AS workYmd
    , A.WORK_SEQ       AS workSeq
    , A.SITE_CD        AS siteCd
    , A.NODE_CD        AS nodeCd
    , A.CHECK_OUT_TIME AS checkOutTime
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.DEL_YN   = 'N'
   AND A.CHECK_IN_TIME IS NOT NULL
   AND A.WORK_YMD >= #{fromYmd}

   AND A.WORK_YMD = #{workYmd}

 ORDER BY A.WORK_YMD DESC, A.WORK_SEQ DESC
 LIMIT 1

/* AppAttd01Mapper.selectSiteGeofence */
SELECT
      S.LAT        AS lat
    , S.LON        AS lon
    , S.GPS_RANGE  AS gpsRange
  FROM TB_SITE S
 WHERE S.CMPNY_CD = #{cmpnyCd}
   AND S.SITE_CD  = #{siteCd}
 LIMIT 1

mapper.update:
/* AppAttd01Mapper.updateCheckOut */
UPDATE TB_USER_ATTD_MGMT
   SET
         CHECK_OUT_DATE   = #{c.checkOutDate}
       , CHECK_OUT_TIME   = #{c.checkOutTime}
       , CHECK_OUT_METHOD = #{c.checkOutMethod}
       , CHECK_OUT_DEVICE_UUID = #{c.deviceUuid}
       , UPDATE_NO        = #{c.userCd}
       , UPDATE_DATE      = NOW()
 WHERE ATTD_ID  = #{c.attdId}
   AND CMPNY_CD = #{c.cmpnyCd}
   AND USER_CD  = #{c.userCd}
   AND DEL_YN   = 'N'
   AND CHECK_OUT_TIME IS NULL

/* AppAttd01Mapper.updateReCheckOut */
UPDATE TB_USER_ATTD_MGMT
   SET
         CHECK_OUT_DATE   = #{c.checkOutDate}
       , CHECK_OUT_TIME   = #{c.checkOutTime}
       , CHECK_OUT_METHOD = #{c.checkOutMethod}
       , CHECK_OUT_DEVICE_UUID = #{c.deviceUuid}
       , UPDATE_NO        = #{c.userCd}
       , UPDATE_DATE      = NOW()
 WHERE ATTD_ID  = #{c.attdId}
   AND CMPNY_CD = #{c.cmpnyCd}
   AND USER_CD  = #{c.userCd}
   AND DEL_YN   = 'N'

